// create date from date string
function parseDate(input, format) {
  format = format || "yyyy-mm-dd"; // default format
  var parts = input.match(/(\d+)/g),
    i = 0,
    fmt = {};

  // extract date-part indexes from the format
  format.replace(/(yyyy|dd|mm)/g, function (part) {
    fmt[part] = i++;
  });

  return new Date(parts[fmt["yyyy"]], parts[fmt["mm"]] - 1, parts[fmt["dd"]]);
}

Ext.define("StarlimsDataGridColumnDateTimePicker", {
  extend: "Ext.form.field.Date",
  alias: "widget.StarlimsDataGridColumnDateTimePicker",
  setValue: function (value) {
    if (value && typeof value === "string") this.m_stringValue = true;
    this.callParent(arguments);
    if (value && typeof value === "string" && !Ext.isDate(this.value)) {
      let _d = parseDate(value, "dd.mm.yyyy");
      if (Ext.isDate(_d) && !isNaN(_d)) this.callParent([_d]);
      else {
        let locale = this.column.Locale
          ? this.column.Locale
          : navigator.language;
        this.callParent([
          Date.Now.toLocaleDateString(locale, {
            day: "2-digit",
            month: "2-digit",
            year: "numeric",
          }),
        ]);
      }
    }
  },
  getValue: function () {
    let v = this.callParent();
    let locale = this.column.Locale ? this.column.Locale : navigator.language;
    if (v) {
      if (this.m_stringValue && v.toLocalDateString !== undefined)
        v.toLocaleDateString(locale, {
          day: "2-digit",
          month: "2-digit",
          year: "numeric",
        });
      else return v;
    } else return v;
  },
});
