Ext.define("StarlimsDataGridTableMethods2", {
  override: "StarlimsDataGridTable",
  All: function All(value) {
    if (Ext.isString(value)) {
      return this._AllById(value);
    }
    if (value instanceof Type) {
      return this._AllByType(value);
    }
    return null;
  },
  _AllById: function _AllById(id) {
    var i, column, childTable, deepElement;
    for (i = 0; i < this.Columns.length; i++) {
      column = this.Columns[i];
      if (column.Id == id) {
        return column;
      }
    }
    for (i = 0; this.ChildTables && i < this.ChildTables.length; i++) {
      childTable = this.ChildTables[i];
      if (childTable.Id == id) {
        return childTable;
      }
      deepElement = childTable._AllById(id);
      if (deepElement) {
        return deepElement;
      }
    }
    return null;
  },
  _AllByType: function _AllByType(type) {
    var all = new ElementCollection(),
      i,
      childTable;
    if (type.Name == "DataGridColumn") {
      for (i = 0; i < this.Columns.length; i++) {
        all.Add(this.Columns[i]);
      }
    }
    for (i = 0; this.ChildTables && i < this.ChildTables.length; i++) {
      childTable = this.ChildTables[i];
      if (type.Name == "DataGridTable") {
        all.Add(childTable);
      }
      all.AddRange(childTable._AllByType(type));
    }
    return all;
  },
});
