  _getFeatureById: function (id) {
    let feature = null;
    const gridView =
      this.view.$className && this.view.$className === "Ext.grid.locking.View"
        ? this.view.lockedView
        : this.view;
    if (gridView)
      return gridView.features.find((current) => {
        return current.id && current.id == id;
      });
    return feature;
  },
