    this.m_dto.GroupMode = lims.undefOrNull(value, "EXPANDED");
    const feature = this._getGroupByFeature();
    if (feature)
      this.m_dto.GroupMode.toLowerCase() == "collapsed"
        ? feature.collapseAll()
        : feature.expandAll();
