  _GetAlternatingColors: function () {
    return this.m_dto.AlternatingColors;
  },
  _SetAlternatingColors: function (value) {
    this.m_dto.AlternatingColors = lims.undefinedOrNullToTrue(value);
    if (this.lockedGrid)
      this.lockedGrid.getView().stripeRows =
        this.normalGrid.getView().stripeRows = this.m_dto.AlternatingColors;
    else this.getView().stripeRows = this.m_dto.AlternatingColors;
    this.getView().refresh();
  },
  _GetFrozenColumns: function () {
    const frozenColumns = lims.undefOrNull(this.m_dto.FrozenColumns, 0);
    if (frozenColumns == 0 || !this.rendered) return frozenColumns;
    const columns = this.ownerGrid.columns || [];
    let frozenCount = 0;
    for (let current of columns) {
      if (lims.undefinedOrNullToFalse(current.locked) === false) break;
      else frozenCount++;
    }
    return (this.m_dto.FrozenColumns = frozenCount);
  },
  _SetFrozenColumns: function (value) {
    const frozenColumns = lims.undefOrNull(value, 0),
      me = this,
      columns = me.ownerGrid.columns || [];
    columns.forEach((current, index, array) => {
      if (
        lims.undefinedOrNullToFalse(current.locked) != false &&
        current.getXType() != "rownumberer" &&
        current.getItemId() != "starlims-row-header"
      )
        me.unlock(current, null, me.normalGrid.headerCt);
    });
    if (frozenColumns > 0 && me.lockedGrid) {
      for (let index = 1; index <= frozenColumns; index++) {
        me.lock(columns[index], null, me.lockedGrid.headerCt);
      }
    }
    me.ownerGrid.m_dto.FrozenColumns = frozenColumns;
  },
