Ext.define("StarlimsTabPageCollection", {
  extend: "StarlimsCollection",
  m_tabControl: null,
  statics: {
    _CreateDummy: function () {
      return new this(new StarlimsTabControl({}));
    },
  },
  constructor: function (tabControl) {
    var me = this;
    this.m_tabControl = tabControl;
    this.callParent([null]);
    if (tabControl == null) return;
    else {
      this._SuspendEvents();
      for (var i = 0; i < tabControl.items.items.length; i++) {
        var pageIndex = this.Add(tabControl.items.items[i]);
        page = tabControl.items.items[pageIndex - 1];
        page.Parent = tabControl;
        if (tabControl.ShowCloseButton === undefined)
          tabControl.ShowCloseButton = false;
        page.Closable = tabControl.ShowCloseButton;
      }
      this._ResumeEvents();
    }
  },
  OnAdd: function (value, index) {
    if (this.m_tabControl == null) return;
    if (value == null) return;
    value.Parent = this.m_tabControl;
    if (this.m_tabControl.ShowCloseButton === undefined)
      this.m_tabControl.ShowCloseButton = false;
    value.Closable = this.m_tabControl.ShowCloseButton;
    if (this.length == 1) value.Selected = true;
    if (!index && this.m_tabControl.items.indexOf(value) == -1)
      this.m_tabControl.add(value);
    else this.m_tabControl.insert(index, value);
    if (value.Selected && this.m_tabControl.rendered)
      this.m_tabControl.setActiveTab(value);
    if (value.Selected && !this.m_tabControl.rendered)
      this.m_tabControl.activeTab = value;
  },
  OnRemove: function (value) {
    this.m_tabControl.remove(value, this.m_tabControl.DisposeOnTabRemove);
  },
  OnClear: function () {
    this.m_tabControl.removeAll();
  },
  FindById: function (id) {
    var me = this;
    for (var i = 0; i < me.m_tabControl.items.length; i++) {
      var myItem = me.rendered
        ? me.m_tabControl.items[i]
        : me.m_tabControl.items.items[i];
      if (myItem.Id === id) return myItem;
    }
    return null;
  },
});
