    this.m_dto.Alignment = value;
    if (this.m_dto.Alignment.ToUpper() === "BOTTOM") {
      this.addCls("x-tab-panel-bottom");
      this.removeCls("x-tab-panel-right");
    } else if (this.m_dto.Alignment.ToUpper() === "RIGHT") {
      this.addCls("x-tab-panel-right");
      this.removeCls("x-tab-panel-bottom");
    }
    var me = this;
    me.setTabPosition(value.toLowerCase());
