  useDTO: false,
  templateHTML:
    '<iframe id="starlimsReportsFrame" name="starlimsReportsFrame" src="htmlruntime/common/pdf.js/web/viewer.html?file={0}#page=1" width="100%" height="100%" frameborder="0" scrolling="no" allowtransparency="yes"></iframe>',
  frameLoaded: false,
  statics: {
    _CreateDummy: function () {
      return new this({});
    },
  },
