Ext.define("StarlimsSplitterPanel", {
  extend: "StarlimsPanel",
  alias: "widget.StarlimsSplitterPanel",
  alternateClassName: ["SL.SplitterPanel"],
  m_Orientation: "",
  tabIndex: -1,
  constructor: function (config) {
    this.callParent([config]);
    if (
      this.items.items &&
      this.items.items.length > 0 &&
      this.items.items[0] instanceof StarlimsSplitContainer
    )
      this.setLayout("fit");
  },
  _DefineProperties: function () {
    var me = this;
    this.callParent();
    Object.defineProperties(me, {
      Orientation: { get: me._GetOrientation, set: me._SetOrientation },
    });
  },
  _SetData: function (value) {
    this.callParent(arguments);
  },
  _GetOrientation: function () {
    return this.m_Orientation;
  },
  _SetOrientation: function (value) {
    this.m_Orientation = value;
  },
  _SetHeight: function (value) {
    if (this.Orientation == "Vertical") return;
    var mySplitContainer = this.up("StarlimsSplitContainerH");
    if (!mySplitContainer) return;
    if (this.flex && this.flex > 0) {
      var otherPanel =
        this.slid == mySplitContainer.Panel1.slid
          ? mySplitContainer.Panel2
          : mySplitContainer.Panel1;
      var splitter = mySplitContainer.down("splitter");
      var hei = mySplitContainer.rendered
        ? mySplitContainer.getHeight()
        : mySplitContainer.height - splitter.rendered
        ? splitter.getHeight()
        : splitter.height - value;
      if (otherPanel.rendered) otherPanel.setHeight(hei);
      else otherPanel.height = hei;
    } else this.setHeight(value);
  },
  _SetWidth: function (value) {
    if (this.Orientation == "Horizontal") return;
    var mySplitContainer = this.up("StarlimsSplitContainerV");
    if (this.flex && this.flex > 0) {
      var otherPanel =
        this.slid == mySplitContainer.Panel1.slid
          ? mySplitContainer.Panel2
          : mySplitContainer.Panel1;
      var splitter = mySplitContainer.down("splitter");
      var wid = mySplitContainer.rendered
        ? mySplitContainer.getWidth()
        : mySplitContainer.width - splitter.rendered
        ? splitter.getWidth()
        : splitter.width - value;
      if (otherPanel.rendered) otherPanel.setWidth(wid);
      else otherPanel.width = wid;
    } else this.setWidth(value);
  },
});
Ext.define("StarlimsTreeUtils", {
  statics: {
    _createTreeNodes: function (tree, dataTable, parentNode) {
      var nameMemberExists = false,
        parentMemberExists = false,
        textMemberExists = false,
        valueMemberExists = false,
        checkMemberExists = false,
        imageMemberExists = false,
        selectedImageMemberExists = false,
        nameMemberColumn,
        parentMemberColumn,
        textMemberColumn,
        valueMemberColumn,
        checkMemberColumn,
        imageMemberColumn,
        selectedImageMemberColumn;
      for (var i = 0; i < dataTable.Columns.Count; i++) {
        var colName = dataTable.Columns[i].ColumnName;
        if (colName.toLowerCase() == tree.NameMember.toLowerCase()) {
          nameMemberExists = true;
          nameMemberColumn = colName;
        }
        if (colName.toLowerCase() == tree.ParentMember.toLowerCase()) {
          parentMemberExists = true;
          parentMemberColumn = colName;
        }
        if (colName.toLowerCase() == tree.TextMember.toLowerCase()) {
          textMemberExists = true;
          textMemberColumn = colName;
        }
        if (colName.toLowerCase() == tree.ValueMember.toLowerCase()) {
          valueMemberExists = true;
          valueMemberColumn = colName;
        }
        if (colName.toLowerCase() == tree.CheckMember.toLowerCase()) {
          checkMemberExists = true;
          checkMemberColumn = colName;
        }
        if (colName.toLowerCase() == tree.ImageMember.toLowerCase()) {
          imageMemberExists = true;
          imageMemberColumn = colName;
        }
        if (colName.toLowerCase() == tree.SelectedImageMember.toLowerCase()) {
          selectedImageMemberExists = true;
          selectedImageMemberColumn = colName;
        }
      }
      var members = {
        nameMemberExists: nameMemberExists,
        nameMemberColumn: nameMemberColumn,
        parentMemberExists: parentMemberExists,
        parentMemberColumn: parentMemberColumn,
        textMemberExists: textMemberExists,
        textMemberColumn: textMemberColumn,
        valueMemberExists: valueMemberExists,
        valueMemberColumn: valueMemberColumn,
        checkMemberExists: checkMemberExists,
        checkMemberColumn: checkMemberColumn,
        imageMemberExists: imageMemberExists,
        imageMemberColumn: imageMemberColumn,
        selectedImageMemberExists: selectedImageMemberExists,
        selectedImageMemberColumn: selectedImageMemberColumn,
      };
      if (!nameMemberExists || !parentMemberExists) {
        for (var i = 0; i < dataTable.Rows.Count; i++) {
          var row = dataTable.Rows[i];
          parentNodes = parentNode == null ? tree.Nodes : parentNode.Nodes;
          StarlimsTreeUtils._dataRowToTreeNode(row, parentNodes, members, tree);
        }
        return;
      }
      var parentName = parentNode == null ? "" : parentNode.Id;
      for (var i = 0; i < dataTable.Rows.Count; i++) {
        var dataRow = dataTable.Rows[i];
        var condition =
          (dataRow[parentMemberColumn] || "").toLowerCase() ==
          parentName.toLowerCase();
        if (!parentName || parentName.length == 0)
          condition = condition || !dataRow[parentMemberColumn];
        if (condition) {
          var parentNodes = parentNode == null ? tree.Nodes : parentNode.Nodes;
          var currentNode = StarlimsTreeUtils._dataRowToTreeNode(
            dataRow,
            parentNodes,
            members,
            tree
          );
          StarlimsTreeUtils._createTreeNodes(tree, dataTable, currentNode);
        }
      }
    },
    _dataRowToTreeNode: function (row, parentNodes, members, tree) {
      var treeNode = new StarlimsTreeNode();
      if (members.nameMemberExists) treeNode.Id = row[members.nameMemberColumn];
      if (members.textMemberExists)
        treeNode.Text = row[members.textMemberColumn];
      if (members.valueMemberExists)
        treeNode.Value = row[members.valueMemberColumn];
      if (members.checkMemberExists) {
        treeNode.Checked = Utils.BoolFromObject(row[members.checkMemberColumn]);
      } else {
        treeNode.Checked = false;
      }
      if (members.imageMemberExists)
        treeNode.Image = row[members.imageMemberColumn];
      if (members.selectedImageMemberExists)
        treeNode.SelectedImage = row[members.selectedImageMemberColumn];
      if (tree.TreeView) {
        treeNode.TreeView = tree.TreeView;
      } else {
        treeNode.TreeView = tree;
      }
      if (!(parentNodes instanceof StarlimsTreeNodeCollection)) {
        parentNodes = new TreeNodeCollection(tree);
      }
      parentNodes.Add(treeNode);
      return treeNode;
    },
    _arrayToTreeNode: function (row, parentNode, treeView) {
      var treeNode = new StarlimsTreeNode();
      treeNode.Id = row.NameMember ? row.NameMember : "";
      treeNode.Text = row.Text ? row.Text : "";
      treeNode.Value = row.Value ? row.Value : "";
      treeNode.Image = row.Image ? row.Image : "";
      treeNode.Expanded = row.Expanded;
      treeNode.SelectedImage = row.SelectedImage ? row.SelectedImage : "";
      treeNode.Checked = row.Checked ? row.Checked : false;
      treeNode.TreeView = treeView;
      treeNode.m_ForeColor = row.ForeColor ? row.ForeColor : "";
      treeNode.m_BackColor = row.BackColor ? row.BackColor : "";
      parentNode.Add(treeNode);
      return treeNode;
    },
    GetDataSet: function (tree) {
      var dt = new System.Data.DataTable("Nodes");
      dt.Columns.Add(tree.NameMember);
      dt.Columns.Add(tree.TextMember);
      dt.Columns.Add(tree.ValueMember);
      dt.Columns.Add(tree.ParentMember);
      dt.Columns.Add(tree.CheckMember);
      dt.Columns.Add(tree.ImageMember);
      dt.Columns.Add(tree.SelectedImageMember);
      this.AddRowsFromTreeNodes(dt, tree.Nodes, "");
      var ds = new System.Data.DataSet("TreeNodes");
      ds.Tables.Add(dt);
      return ds;
    },
    AddRowsFromTreeNodes: function (dataTable, nodes, parentNodeId) {
      nodes.forEach(function (node) {
        var nodeId = node.Id;
        if (nodeId == null) nodeId = "Node_" + System.Guid.NewGuid().ToString();
        dataTable.Rows.Add(
          nodeId,
          node.Text,
          node.Value,
          parentNodeId,
          node.Checked,
          node.Image,
          node.SelectedImage
        );
        if (node.Nodes.Count > 0)
          AddRowsFromTreeNodes(dataTable, node.Nodes, nodeId);
      });
    },
  },
});
