Ext.define("StarlimsLinkBarItem", {
  extend: "StarlimsCommandBarItem",
  alias: "widget.StarlimsLinkBarItem",
  alternateClassName: ["SL.LinkBarItem", "LinkBarItem"],
  statics: {
    _CreateDummy: function () {
      return new this({});
    },
  },
  constructor: function (config) {
    var me = this;
    me.callParent(arguments);
    me.layout = { type: "hbox", align: "stretch", padding: "2px", pack: "fit" };
    me.add({
      xtype: "image",
      alt: "Image",
      src: config
        ? config.Image
          ? config.Image.replace("GetImageById.lims", "GetImageByIdHD.lims")
          : ""
        : "",
      height: 15,
      width: 15,
      margin: "0 10 0 10",
    });
    me.add({
      xtype: "label",
      text: config ? (config.Text ? config.Text : "") : "",
      listeners: {
        render: function (c) {
          c.getEl().on("mouseover", function () {
            if (this.el.dom.style.cursor == "default") {
              this.el.dom.style.cursor = "pointer";
              this.el.dom.style.textDecoration = "underline";
            }
          });
          c.getEl().on("mouseout", function () {
            this.el.dom.style.cursor = "default";
            this.el.dom.style.textDecoration = "none";
          });
        },
        afterrender: function (c) {
          if (me.Group && me.Group.Parent) {
            var valStyle = me.Group.Parent._GetStyleString();
            var elementAlign =
              me.Group.Parent.m_dto.RightToLeft.toUpperCase() === "YES"
                ? "right"
                : "left";
            var itemElementAlign =
              me.Group.Parent.m_dto.RightToLeft.toUpperCase() === "YES"
                ? "end"
                : "start";
            Ext.get(me.id + "-targetEl").select(
              ".x-component"
            ).elements[0].style = valStyle;
            if (
              (elementAlign == "right" && me.layout.pack != "end") ||
              (elementAlign == "left" && me.layout.pack == "end")
            ) {
              var temp = me.items.items[1];
              me.items.items[1] = me.items.items[0];
              me.items.items[0] = temp;
            }
            me.layout.pack = itemElementAlign;
            me.focusable = me.m_dto.TabStop;
            if (me.el.dom) {
              me.Group.Parent._domTraverse(me.el.dom);
            }
            c.el.dom.style.width = me.Group.Parent.Width - 55 + "px";
            c.el.dom.style.wordWrap = "break-word";
          }
          me.updateLayout();
        },
      },
    });
    if (config) {
      me.Id = config.Id ? config.Id : Ext.id();
      me.Text = config.Text ? config.Text : "";
      me.Image = config.Image
        ? config.Image.replace("GetImageById.lims", "GetImageByIdHD.lims")
        : "";
      me.Value = config.Value ? config.Value : "";
      if (config.ToolTip) me._SetToolTip(config.ToolTip);
      me._ChangeStyle();
    }
    if (this.Value) {
      this.AutomationId = this.Value;
      me.on("afterrender", (sender, options) => {
        me.getEl()
          .dom.querySelector("label")
          .setAttribute("automation-id", me.Value);
      });
    }
  },
  _SetText: function _SetText(value) {
    if (!value) value = "";
    Utils.checkArguments(arguments, ["String"]);
    var me = this;
    me.m_Text = value;
    if (me.child("[xtype=label]")) me.child("[xtype=label]").setText(value);
  },
  _SetToolTip: function _SetTooltip(value) {
    if (!value) value = "";
    Utils.checkArguments(arguments, ["String"]);
    var me = this;
    if (me.getEl()) me.getEl().set({ "data-qtip": value });
  },
  _GetText: function _GetText() {
    return this.m_Text;
  },
  _getImage: function _getImage() {
    return this.m_Image;
  },
  _setImage: function _setImage(value) {
    Utils.checkArguments(arguments, [["String", null]]);
    this.m_Image = value.replace("GetImageById.lims", "GetImageByIdHD.lims");
    var image = this.child("[xtype=image]");
    if (image) image.setSrc(value);
    else console.log("Image " + value + " not found!");
  },
  _getValue: function _getValue() {
    return this.m_Value;
  },
  _setValue: function _setValue(value) {
    this.m_Value = value;
  },
});
