      e.stopSelection = true;
      var eventArgs = new VariablesTable();
      eventArgs["node"] = node.data;
      eventArgs["ColumnPos"] = e.position.colIdx;
      eventArgs["Column"] = e.position.column;
      eventArgs["Cancel"] = false;
      me.fireEvent("OnBeforeCheck", me, eventArgs);
