Ext.define("starlimsSpreadsheetSelection", {
  override: "Ext.grid.selection.SpreadsheetModel",
  privates: {
    getNumbererColumnConfig: function () {
      var me = this;
      return {
        xtype: "rownumberer",
        locked: me.hasLockedHeader,
        defaultRenderer: function (
          value,
          metaData,
          record,
          rowIdx,
          colIdx,
          dataSource,
          view
        ) {
          var me = this,
            rowspan = me.rowspan,
            page = dataSource.currentPage,
            result = record ? view.store.indexOf(record) : value - 1;
          if (view.panel.ownerGrid.m_RowHeaderUseLetters) {
            if (metaData && rowspan) {
              metaData.tdAttr = 'rowspan="' + rowspan + '"';
            }
            if (page > 1) {
              result += (page - 1) * dataSource.pageSize;
            }
            if (view.panel.ownerGrid.m_RowLettersAreReversed) {
              result = view.panel.ownerGrid.PlateRows - result - 1;
            }
            if (result > 25) {
              return (
                String.fromCharCode(64 + result / 26) +
                String.fromCharCode(65 + (result % 26))
              );
            } else {
              return String.fromCharCode(65 + result);
            }
          } else return result + 1;
        },
      };
    },
  },
  selectCells: function (rangeStart, rangeEnd, suppressEvent, noReset) {
    var me = this,
      view = me.view.ownerGrid.view,
      sel;

    rangeStart = rangeStart.isCellContext
      ? rangeStart.clone()
      : new Ext.grid.CellContext(view).setPosition(rangeStart);
    rangeEnd = rangeEnd.isCellContext
      ? rangeEnd.clone()
      : new Ext.grid.CellContext(view).setPosition(rangeEnd);
    if (!noReset) me.resetSelection(true);
    me.selected = sel = new Ext.grid.selection.Cells(rangeStart.view);
    sel.setRangeStart(rangeStart);
    sel.setRangeEnd(rangeEnd);
    if (!suppressEvent) {
      me.fireSelectionChange();
    }
  },
  selectByPosition: function (position, noReset) {
    var me = this;
    position = new Ext.grid.CellContext(me.view).setPosition(
      position.row,
      position.column
    );
    if (me.getCellSelect()) me.selectCells(position, position, false, noReset);
    else if (me.getRowSelect()) this.select(position.record);
    else if (me.getColumnSelect()) me.selectColumn(position.column);
  },
  deselectAll: function (suppressEvent) {
    var me = this,
      sel = me.selected;
    if (sel && sel.getCount()) {
      sel.selectAll();
      sel.clear();
      sel.allSelected = false;
      me.updateHeaderState();
      if (!suppressEvent) {
        me.fireSelectionChange();
      }
    }
  },
});
Ext.override(Ext.grid.CellContext, {
  setPosition: function (row, col) {
    var me = this;
    if (arguments.length === 1) {
      if (row.length) {
        col = row[0];
        row = row[1];
      } else if (row.isCellContext) {
        return me.setAll(
          row.view,
          row.rowIdx,
          row.colIdx,
          row.record,
          row.column
        );
      } else {
        if (row.view) {
          me.view = row.view;
        }
        col = row.column;
        row = row.row;
      }
    }
    if (row != null) me.setRow(row);
    if (col != null) me.setColumn(col);
    return me;
  },
});
