  _GetFont: function _GetFont() {
    return this.m_Font;
  },
  _SetFont: function (value) {
    if (value === null) return;
    var me = this;
    var Font = MindFusion.Drawing.Font;
    me.m_Font = value;
    me.m_FontFamily = "";
    me.m_FontSize = "";
    me.m_FontBold = null;
    me.m_FontItalic = null;
    var fontDefinition = value.split(",");
    if (fontDefinition.length > 0 && fontDefinition[0])
      me.m_FontFamily = fontDefinition[0].Trim();
    if (fontDefinition.length > 1 && fontDefinition[1]) {
      var firstChar = fontDefinition[1].Trim().toLowerCase().indexOf("p");
      if (firstChar > 0)
        me.m_FontSize = fontDefinition[1].Trim().substring(0, firstChar);
      else me.m_FontSize = fontDefinition[1].Trim();
    }
    if (fontDefinition.length > 0 && fontDefinition[2])
      me.m_FontBold = fontDefinition[2].Trim();
    if (fontDefinition.length > 0 && fontDefinition[3])
      me.m_FontItalic = fontDefinition[3].Trim();
    if (me.m_FontBold == "false") {
      me.m_FontBold = null;
    }
    if (me.m_FontItalic == "false") {
      me.m_FontItalic = null;
    }
    for (var i = 0; i < me.Nodes.Count; i++) {
      me.Nodes[i].m_diagram_shapeNodeRef.setFont(
        new Font(
          me.m_FontFamily,
          Number(me.m_FontSize),
          me.m_FontBold,
          me.m_FontItalic
        )
      );
    }
    for (var i = 0; i < me.Links.Count; i++) {
      me.Links[i].m_diagramLinkRef.setFont(
        new Font(
          me.m_FontFamily,
          Number(me.m_FontSize),
          me.m_FontBold,
          me.m_FontItalic
        )
      );
    }
  },
