  _setXMLDataAfterInitialization: function () {
    var me = this;
    if (me.l_XMLData != null && me.l_XMLData != "") {
      var parser = new DOMParser();
      var xmlDoc = parser.parseFromString(me.l_XMLData, "text/xml");
      me.diagram.fromXmlDocument(xmlDoc);
      for (var i = 0; i < me.diagram.nodes.length; i++) {
        var node = new StarlimsDiagramShapeNode(me.diagram.nodes[i]);
        node.Parent = me;
        me.Nodes.Add(node);
      }
      for (var i = 0; i < me.diagram.links.length; i++) {
        var link = new StarlimsDiagramLink(me.diagram.links[i]);
        link.Parent = me;
        me.Links.Add(link);
      }
      me.l_XMLData = null;
    }
  },
