  _AddRowsFromDiagram: function (dt, nodes, ParentNodeId, isChildNode) {
    for (var i = 0; i < nodes.length; i++) {
      var shape = nodes[i].Shape;
      var alreadyExists = dt.Select(function (curRec) {
        if (curRec["NameMember"] == nodes[i].Id) {
          return true;
        }
      });
      dt.Rows.Add(
        nodes[i].Id,
        ParentNodeId,
        nodes[i].Text,
        nodes[i].Value,
        nodes[i].Image,
        nodes[i].ImageAlign,
        shape,
        nodes[i].EnabledHandles,
        nodes[i].Expandable,
        nodes[i].Transparent,
        nodes[i].X,
        nodes[i].Y,
        nodes[i].Width,
        nodes[i].Height
      );
      if (alreadyExists.length == 0) {
        if (nodes[i].Nodes.Count > 0)
          this._AddRowsFromDiagram(dt, nodes[i].Nodes, nodes[i].Id, true);
      }
    }
  },
