Ext.override(Ext.container.Container, {
  initComponent: function () {
    var me = this;
    me.callParent();
    me.on({
      afterrender: function (container, eOpts) {
        var me = this;
        if (!container.monitorOnLeave) return;
        if (container.getXType().toLowerCase() === "airoweditor")
          container.on("focusenter", me.focusEnter, me);
        else container.on("focusleave", me.focusLeave, me);
      },
    });
  },
  focusEnter: function (component, event, eOpts) {
    var me = this;
    Ext.getDoc().on("mousedown", me.mouseDown, me);
  },
  focusLeave: function (component, event, eOpts) {
    var me = this;
    return me.updateProviderUpdate(event);
  },
  _ignoredClickElements: [
    "datepicker",
    "boundlist",
    "common-popup",
    "common-wizard",
  ],
  isElementInside: function (target) {
    var me = this,
      target = target,
      plugin =
        me.xtype === "airowediting" ? me.getInitialConfig().editingPlugin : me,
      allIgnored = plugin.ignoredClickElements
        ? me._ignoredClickElements.concat(plugin.ignoredClickElements)
        : me._ignoredClickElements;
    while (target) {
      if (
        !allIgnored.some(function (element, index, array) {
          return target.className.indexOf(element) >= 0;
        })
      ) {
        target = target.parentElement;
      } else return true;
    }
    return false;
  },
  updateProviderUpdate: function (event) {
    var me = this;
    if (me.isElementInside(event.relatedTarget)) return false;
    var containerId = me.getItemId() || me.getReference() || me.getId();
    var viewModelName = me.viewModelName;
    var currentContainer = me;
    while (currentContainer) {
      if (currentContainer.getViewModel()) {
        if (currentContainer.getViewModel().get(viewModelName)) {
          var model = currentContainer.getViewModel().get(viewModelName);
          if (model.dirty) {
            var validInput = me._validateInput(containerId, model);
            if (validInput) {
              var store = model.store;
              if (store) store.fireEvent("updateProviderSync", containerId);
            } else {
              Ext.MessageBox.confirm(
                GetResource(me, "Question"),
                GetResource(
                  me,
                  "Unable to save changes. Do you want to correct the errors?"
                ),
                function (choice) {
                  if (choice == "no" || choice == "cancel") {
                    model.reject();
                    return true;
                  }
                  return false;
                }
              );
            }
          }
        }
      }
      currentContainer = currentContainer.ownerCt;
    }
    return true;
  },
  _validateInput: function (containerId, model) {
    var me = this,
      valid = true,
      errors = [],
      formView = Ext.ComponentQuery.query("#" + containerId)[0];
    if (formView && formView instanceof Ext.form.Panel)
      if (model && model instanceof Ext.data.Model && !model.isValid()) {
        valid = false;
        Ext.iterate(model.getValidation().getData(), function (field, value) {
          if (value != true) errors.push({ field: field, message: value });
        });
      }
    if (!valid) formView.getForm().markInvalid(errors);
    return valid;
  },
});
