Ext.define("Starlims.JSONWriter", {
  extend: "Ext.data.writer.Json",
  alias: "writer.aijsonwriter",
  write: function (request) {
    var operation = request.getOperation(),
      records = operation.getRecords() || [],
      len = records.length,
      data = [],
      envelope = [],
      extra = [],
      i;
    for (i = 0; i < len; i++) {
      data.push(this.getRecordData(records[i], operation));
    }
    envelope.push(data);
    extra.push(envelope);
    return this.writeRecords(request, extra);
  },
  getRecordData: function (record, operation) {
    var me = this,
      changes = null,
      recordAsArray = [],
      modifiedFields = [],
      proxy = record.getProxy();
    if (!(changes = record.getChanges())) return me.callParent(arguments);
    Object.keys(changes).forEach(function (currentValue, index, array) {
      var fieldInfo = [];
      fieldInfo.push(
        record.getField(currentValue).dataMember ||
          record.getField(currentValue).name
      );
      fieldInfo.push(record.get(currentValue));
      fieldInfo.push(proxy.tableMetadata.getFieldType(currentValue));
      fieldInfo.push(record.getModified(currentValue));
      modifiedFields.push(fieldInfo);
    });
    recordAsArray.push(proxy.starlimsParentControlId);
    recordAsArray.push(proxy.tableMetadata.getTableName());
    recordAsArray.push(modifiedFields);
    recordAsArray.push(record.get(record.getIdProperty() || "ORIGREC"));
    recordAsArray.push("");
    return recordAsArray;
  },
});
