      var me = this;
      var h = function msgBox_Handler(buttonId, value, opt) {
        if (Ext.isFunction(theCallBack)) {
          theCallBack.call(
            null,
            opt.buttonText[buttonId] != null
              ? opt.buttonText[buttonId].toUpperCase()
              : buttonId.toUpperCase(),
            value
          );
        }
        Dialogs.__FocusCurrentControl();
      };
